// Original Chinese narration, checked against the linked sources on 2026-10-28.
// Time rules describe the 2026 reference year; future invitations use device IANA data.
const p=(heading,text)=>({heading,text});
function country(id,title,subtitle,region,focus,summary,paragraphs,takeaways,sourceIds){return {id:`country-${id}`,type:'country',title,subtitle,region,country:title,cityId:null,focus,summary,paragraphs,takeaways,sourceIds};}
function city(id,title,countryName,region,lat,lon,subtitle,summary,paragraphs,takeaways,sourceIds){return {id:`city-${id}`,type:'city',title,subtitle,region,country:countryName,cityId:id,focus:{lat,lon},summary,paragraphs,takeaways,sourceIds};}

